INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pv-foerderung-letzter-foerdercall-2026-speicherbonus-2027','PV-Förderung: Letzter Fördercall endet heute, ab 2027 Speicherbonus','Der letzte PV-Fördercall nach dem alten EAG-System läuft nur noch bis heute 23:59 Uhr. Ab 2027 soll ein Speicherbonus mit Pflicht zum intelligenten Energiemanagement folgen.','Die **PV-Förderung** nach dem bisherigen System des Erneuerbaren-Ausbau-Gesetzes (EAG) geht heute zu Ende: Der dritte und letzte Fördercall des Jahres 2026 für Photovoltaikanlagen läuft nur noch bis Donnerstag, 22. Oktober, 23:59 Uhr. Wer bereits ein Ticket gezogen hat, muss den Antrag im EAG-Portal bis dahin abschließen. Ab 2027 stellt die Bundesregierung die Unterstützung für Sonnenstrom grundlegend um.

## Letzter Fördercall: Was jetzt noch gilt

Der Call startete am 8. Oktober um 17 Uhr mit der Ticketziehung. Die Einreichung läuft ausschließlich über das Portal der EAG-Abwicklungsstelle. Laut Abwicklungsstelle ist das Ticket der erste Schritt; für die folgenden Antragsschritte ist keine eigene Bestätigungsmail zum Ticket nötig.

Gefördert werden in dieser Runde neue oder erweiterte PV-Anlagen sowie damit verbundene Stromspeicher. Laut Energie-Staatssekretärin Elisabeth Zehetner (ÖVP) stehen rund 38,5 Millionen Euro zur Verfügung. Dabei handelt es sich nicht um frisches Geld, sondern um Restmittel aus früheren Runden, die frei wurden, weil Projekte nicht oder nur teilweise umgesetzt wurden. Ursprünglich waren für diesen Call nur acht Millionen Euro eingeplant.

Wer tatsächlich zum Zug kommt, entscheidet sich erst nach Ende der Frist. Es ist zugleich die letzte Runde nach dem Prinzip „first come, first served“.

## Hohe Nachfrage bei der PV-Förderung

Wie groß das Interesse ist, zeigte bereits der zweite Fördercall 2026: Laut Wirtschafts- und Energieministerium (BMWET) waren die Mittel damals nach 33 Sekunden ausgeschöpft. Rund 28.000 Anträge konkurrierten um Förderungen für etwa 3.000 Projekte. Auch beim aktuellen Call war der Andrang in den ersten Minuten sehr groß, berichten Regionalmedien.

Für Antragsteller heißt das: Eine Einreichung ist keine Garantie für eine Zusage. Wer leer ausgeht, sollte die Regeln für 2027 kennen, bevor er eine Anlage beauftragt.

## Ab 2027: Speicherbonus statt Investitionszuschuss

Das Ministerium hat Anfang Oktober die Grundzüge des neuen Modells vorgestellt. Die Details werden noch verhandelt. Die wichtigsten Eckpunkte:

- Der klassische Investitionszuschuss für PV-Anlagen soll durch einen **Speichersystembonus** ersetzt werden. Gefördert werden neue Speicher bei neuen Anlagen sowie nachgerüstete Speicher bei bestehenden Anlagen.
- Voraussetzung ist ein intelligentes Energiemanagement, das den Speicher netz- und systemdienlich steuert.
- Bei neuen Speichern in Kombination mit neuen PV-Anlagen soll ein Wechselrichter aus europäischer Produktion Pflicht werden. Bei Nachrüstungen bleibt ein Made-in-Europe-Bonus möglich.
- Statt kurzer Fördercalls soll laufend eingereicht werden können, und zwar nach Fertigstellung des Projekts.
- Speicherprojekte, die 2026 keine EAG-Förderung erhalten haben und ab 1. November 2026 abgerechnet oder in Betrieb genommen werden, sollen 2027 im neuen System einreichen dürfen.

Noch offen sind Fördersätze, Bonushöhe, technische Kriterien und das Budget. Diese Punkte sollen in der jährlichen Investitionszuschüsse-Verordnung festgelegt werden. Für die nötige Gesetzesänderung braucht es im Nationalrat eine Zweidrittelmehrheit.

## Was Haushalte jetzt beachten sollten

Für Eigenheimbesitzer, die eine Anlage planen, ergeben sich aus dem Systemwechsel einige praktische Punkte:

1. Laufende Anträge im aktuellen Call bis heute 23:59 Uhr vollständig abschließen.
2. Bei einem Projekt mit Speicher, das ab November fertig wird, Rechnungen und Inbetriebnahme sauber dokumentieren – das kann für die Einreichung 2027 relevant sein.
3. Beim Angebot auf Wechselrichter und Energiemanagement achten, weil beides im neuen Modell eine zentrale Rolle spielen soll.
4. Die endgültige Verordnung abwarten, bevor mit fixen Förderbeträgen kalkuliert wird.

Auf Landes- und Gemeindeebene gibt es teilweise eigene Förderungen, die unabhängig vom Bundesprogramm laufen. Ein Blick auf die Angebote des eigenen Bundeslandes lohnt sich daher in jedem Fall.','energie','Förderungen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/pv-foerderung-letzter-foerdercall-2026-speicherbonus-2027.webp','BMWET / EAG-Abwicklungsstelle','https://www.bmwet.gv.at/Presse/AktuellePressemeldungen/pv-foerderung-wird-systemfoerderung.html','published','2026-10-22T13:50:00.000Z','2026-10-22T13:44:47.730Z','PV-Förderung: Letzter Fördercall 2026 endet heute','PV-Förderung: Der letzte EAG-Fördercall endet am 22. Oktober um 23:59 Uhr. Was jetzt gilt und wie der Speicherbonus ab 2027 aussehen soll.','PV-Förderung','["PV-Förderung","Fördercall Photovoltaik","PV-Förderung 2027","Speicherbonus","EAG Förderung","Photovoltaik Förderung Österreich","Stromspeicher Förderung 2027","Made in Europe Wechselrichter"]','PV-Förderung: Einfamilienhaus mit Photovoltaikanlage und Stromspeicher in Österreich','Austrian single-family house roof with solar panels in late afternoon autumn light, a wall-mounted home battery storage unit visible in an open garage below, rural Lower Austria landscape with vineyards in the background, no text, no logos, no readable signs, no people','[{"q":"Bis wann läuft der letzte PV-Fördercall 2026?","a":"Bis Donnerstag, 22. Oktober 2026, 23:59 Uhr. Anträge werden über das Portal der EAG-Abwicklungsstelle eingereicht."},{"q":"Was ändert sich bei der PV-Förderung ab 2027?","a":"Statt eines Investitionszuschusses für PV-Anlagen soll es einen Speicherbonus geben, verbunden mit intelligentem Energiemanagement und laufender Einreichung nach Projektabschluss."},{"q":"Stehen die Fördersätze für 2027 schon fest?","a":"Nein. Fördersätze, Bonushöhe und Budget sollen erst in der Investitionszuschüsse-Verordnung festgelegt werden."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excl